/* AdvogadoJá · Módulo independente · execução local sem dependência externa */
(()=>{'use strict';
if(new URLSearchParams(location.search).has('embed'))document.body.classList.add('embedded');
const IN_WORKSPACE=new URLSearchParams(location.search).get('workspace')==='1';
const $=s=>document.querySelector(s), app=$('#app'), S={bundle:null,screen:null,mode:'campos',query:'',journey:null,subjourney:null,device:'mobile',scenario:null,roteiro:null,step:0,history:[],modal:null,changes:0,bankView:'campos',branchChoices:{},showCount:24,fieldPath:["identidade","id"],fieldQuery:"",flowDetailTab:"saidas",dragId:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dt=v=>Array.isArray(v)?v:[];
const idEsc=v=>esc(v).replace(/`/g,'');
const scr=()=>S.bundle?.telas||{}, screenIDs=()=>Object.keys(scr()).sort(), current=()=>scr()[S.screen]||null;
const tOf=id=>scr()[id]?.tela||{};
const nameOf=id=>tOf(id).identidade?.nomeExibicao||tOf(id).identidade?.nome||id;
const moduleName=()=>({BANCO:'Banco',FLUXO:'Fluxo',JORNADAS:'Jornadas',PROTOTIPO:'Protótipo'})[MODULO]||MODULO;
const make=(tag,cls='',html='')=>{const el=document.createElement(tag);if(cls)el.className=cls;el.innerHTML=html;return el};
const pathFor=o=>Object.entries(o||{}).filter(([_,v])=>v!=null).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v).slice(0,85):String(v).slice(0,85)}`).join(' · ');
const jIndex=()=>{
 const m=new Map();for(const id of screenIDs())for(const p of dt(tOf(id).classificacao?.jornadas)){
  const j=p.jornada||{},sj=p.subjornada||{};if(!j.id)continue;
  if(!m.has(j.id))m.set(j.id,{id:j.id,name:j.nome||j.id,order:j.ordem??999,subs:new Map()});
  const group=m.get(j.id),sk=sj.id||'_sem_subjornada';if(!group.subs.has(sk))group.subs.set(sk,{id:sk,name:sj.nome||'Sem subjornada',order:sj.ordem??999,items:[]});
  group.subs.get(sk).items.push({id,p,order:p.ordemTela??999});
 }
 return [...m.values()].sort((a,b)=>a.order-b.order||a.name.localeCompare(b.name));
};
function nav(){const active=S.mode==='campos'?'fields':'visual';return `<div class="eyebrow">ESTRUTURA</div><div class="module"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M6 4v6h12M6 10v10h12M18 7v6M18 17v6"/></svg>Fluxo <span class="arrow">⌄</span></div><nav class="subitems" aria-label="Subitens do Fluxo"><button type="button" class="subitem ${active==='fields'?'active':''}" data-nav="campos" ${active==='fields'?'aria-current="page"':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 4h16v16H4zM4 10h16M10 10v10"/></svg>Campos utilizados</button><button type="button" class="subitem ${active==='visual'?'active':''}" data-nav="visualizacao" ${active==='visual'?'aria-current="page"':''}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="3" width="7" height="6" rx="1"/><rect x="14" y="15" width="7" height="6" rx="1"/><path d="M10 6h4v12"/></svg>Visualização do fluxo</button></nav><p class="caption">Mesmo domínio, duas formas de leitura. Dados vindos exclusivamente deste módulo, sem duplicações.</p>`}
function header(){return `<div class="top-brand"><div class="top-mark">AJ</div><div><strong>AdvogadoJá</strong><small>WORKSPACE UNIFICADO · FLUXO</small></div></div><div class="top-right"><span id="saveStatus">${S.changes?'Alterações não exportadas':'Dados do módulo'}</span><button class="top-action" data-action="import">Importar JSON</button><button class="top-action primary" data-action="export">↓ Exportar JSON</button></div>`}
function topTitle(){const isField=S.mode==='campos',name=isField?'Campos utilizados':'Visualização do fluxo';return `<div class="crumb">Workspace › Fluxo › ${name}</div><div class="section-row"><div><h1>Fluxo · ${name}</h1><p>${isField?'Leitura dos campos necessários ao Fluxo, com árvore e detalhes no padrão do P7.':'Sequências, decisões, ramificações e prévias das telas no Fluxo V2.'}</p></div><span class="source">${isField?'Padrão visual · Projeto 7':'Padrão visual · Fluxo V2'}</span></div><div class="mobile-choices"><button type="button" data-nav="campos" class="${isField?'active':''}">Campos utilizados</button><button type="button" data-nav="visualizacao" class="${!isField?'active':''}">Visualização do fluxo</button></div><div class="info"><span>${isField?'Campos obtidos diretamente do contrato modular de cada tela.':'Sequências e relações carregadas diretamente do modulo.json.'}</span></div>`}
function shell(){app.innerHTML=`<div class="shell"><header class="top">${header()}</header><div class="layout"><aside class="sidebar" aria-label="Navegação de módulos">${nav()}</aside><main id="main" class="content"><div class="content-header">${topTitle()}</div><div class="frame-zone"><section id="pane" class="screen active screen-view" aria-label="Conteúdo do Fluxo"></section></div></main></div></div><input id="fileLoader" type="file" accept=".json,application/json" hidden>`;renderPane();
if(IN_WORKSPACE&&window.parent!==window){const menu=[{id:'campos',label:'Campos utilizados',kind:'mode'},{id:'visualizacao',label:'Visualização do fluxo',kind:'mode'}];window.parent.postMessage({type:'aj.workspace.module-state',module:MODULO,mode:S.mode,menu},location.origin)}
}
function setMode(mode){if(mode==='fields')mode='campos';if(mode==='visual')mode='visualizacao';S.mode=mode==='campos'?'campos':'visualizacao';try{history.replaceState({},'',location.pathname+location.search+'#'+(S.mode==='campos'?'fields':'visual'))}catch(_){}shell()}
function renderPane(){const pane=$('#pane');if(!pane)return;pane.innerHTML=S.mode==='campos'?fieldsView():flowView();injectFrames(pane)}
function screensSelect(selected=S.screen,selId='screenSelect'){return `<select id="${selId}" aria-label="Tela">${screenIDs().map(id=>`<option value="${esc(id)}" ${id===selected?'selected':''}>${esc(nameOf(id))} · ${esc(id)}</option>`).join('')}</select>`}
function countNodes(v,limit=15000){let count=0,leaves=0;function rec(x,d){if(++count>=limit||d>16)return;if(x&&typeof x==='object'){const vals=Object.values(x);if(!vals.length)leaves++;for(const t of vals){if(count>=limit)break;rec(t,d+1)}}else leaves++}rec(v,0);return {nodes:Math.max(count-1,0),leaves}}
function fieldValue(path){let v=tOf(S.screen);for(const k of path||[]){if(v==null||!Object.prototype.hasOwnProperty.call(v,k))return undefined;v=v[k]}return v}
function fieldTreeHtml(v,path=[],depth=0){if(depth>9)return '';const entries=(v&&typeof v==='object')?Object.entries(v):[];return entries.map(([key,val],i)=>{const p=[...path,key],txt=p.join('.'),q=(S.fieldQuery||'').toLocaleLowerCase('pt-BR'),selected=JSON.stringify(S.fieldPath||[])===JSON.stringify(p),expand=val!==null&&typeof val==='object'&&Object.keys(val).length>0,kind=Array.isArray(val)?'lista':val===null?'nulo':typeof val==='object'?'objeto':typeof val,pathJson=esc(JSON.stringify(p));if(q&&!txt.toLocaleLowerCase('pt-BR').includes(q)&&!JSON.stringify(val).toLocaleLowerCase('pt-BR').includes(q))return '';const name=Array.isArray(v)?'#'+key:key;const open=depth===0||p.slice(0,1).join('')===S.fieldPath?.[0]&&depth<2;const needed=['identidade','classificacao','navegacao','estados','acoes','interacoes'].includes(p[0]);return `<details class="f-tree-node" ${open?'open':''}><summary class="${selected?'selected':''} ${needed?'needed':'unprioritized'}" data-field="${pathJson}" title="${esc(txt)}"><span class="f-tree-arrow">${expand?'▸':'·'}</span><span class="f-tree-leaf">${esc(name)}</span><span class="f-tree-kind">${kind}</span></summary>${expand?`<div class="f-tree-children">${fieldTreeHtml(val,p,depth+1)}</div>`:''}</details>`}).join('')}
function fieldDetails(){const p=Array.isArray(S.fieldPath)&&S.fieldPath.length?S.fieldPath:['identidade','id'];const value=fieldValue(p),name=p[p.length-1]||'tela',kind=Array.isArray(value)?'lista':value===null?'nulo':typeof value==='object'?'objeto':typeof value;const out=JSON.stringify(value===undefined?null:value,null,2);const path=p.join('.');const about=path==='identidade.id'?'Identificador estável e único de cada tela. Permite vincular nós e resolver referências de origem e destino.':path.startsWith('classificacao.jornadas')?'Organiza a participação desta tela nas jornadas e subjornadas, incluindo ordem e contexto.':path.startsWith('navegacao.relacoes')?'Informa destinos, gatilhos, condições e caminhos possíveis declarados para o Fluxo.':path.startsWith('navegacao')?'Declara o modo como esta tela se conecta às demais telas e estados do Fluxo.':path.startsWith('acoes')?'Expõe as ações disponíveis para disparar eventos e transições do Fluxo.':path.startsWith('estados')?'Descreve estados e condições que modificam a experiência da tela.':path.startsWith('componentes')?'Identifica os componentes e seus pontos de montagem visual.':'Campo que pode contribuir para identificação, ordenação, apresentação ou transição conforme o contrato declarado.';const important=['identidade','classificacao','navegacao','estados','acoes','interacoes'].includes(p[0]);return `<div class="f-panel-head"><div><div class="f-eyebrow">02 / DETALHES</div><h3>O que o Flow precisa ler</h3></div><span class="f-chip soft">Leitura do motor</span></div><div class="f-detail-scroll"><div class="f-eyebrow">LEITURA POR MOTOR</div><div class="f-detail-title">${esc(String(name))}</div><code class="f-path">${esc(path)}</code><p class="f-detail-hint" style="margin:8px 0 14px">Tipo: ${esc(kind)} · ${value&&typeof value==='object'?Object.keys(value).length+' propriedades':'Campo individual'}</p><div class="f-detail-pills">${important?'<span class="f-important">✓ Flow precisa deste campo.</span>':'<span>Campo disponível no contrato.</span>'}</div><div class="f-detail-label">Qual funcionalidade precisa e por quê</div><div class="f-about">${esc(about)}</div><div class="f-detail-label">Valor no JSON do módulo</div><pre class="f-json">${esc(out)}</pre><details class="f-edit-details"><summary>Editar valor JSON deste campo</summary><textarea spellcheck="false" id="fieldEditor" class="f-field-edit" aria-label="Editar campo em JSON">${esc(out)}</textarea><div class="f-detail-actions"><button class="f-btn primary" data-action="saveField">Aplicar alteração</button><button class="f-btn" data-action="copyField">Copiar campo</button><button class="f-btn" data-action="showJson">JSON da tela</button></div><p class="f-detail-hint">As alterações só saem deste navegador quando o JSON for exportado.</p></details></div>`}
function fieldsView(){const id=S.screen||screenIDs()[0],t=tOf(id),stats=countNodes(t),rels=getRels(id),part=dt(t.classificacao?.jornadas);if(!S.fieldPath||fieldValue(S.fieldPath)===undefined)S.fieldPath=t.identidade?.id?['identidade','id']:['identidade'];const counts={jornadas:part.length,relacoes:rels.length,entradas:dt(t.navegacao?.entradas).length,componentes:Object.keys(current()?.componentes||{}).length};const focusButtons=[['Jornadas e ocorrências',['classificacao','jornadas']],['Bifurcações e caminhos',['navegacao','relacoes']],['Relações e destinos',['navegacao','relacoes']],['Ações e condições',['acoes']],['Componentes e slots',['estrutura']],['Apresentação',['estrutura','html']]];return `<div class="fields-app"><div class="f-main"><div class="f-mode-intro f-first-intro"><div><div class="f-eyebrow">MÓDULO / FLOW</div><h2>Flow · campos necessários</h2><p>Leitura do contrato modular: nós, jornadas, ocorrências, bifurcações, caminhos, relações e prévia. O motor apenas vincula IDs explícitos.</p></div><div class="f-metric naked"><strong>${stats.leaves}</strong><small>campos nesta tela</small></div></div><section class="f-read-summary"><div class="f-read-top"><div><div class="f-eyebrow">MODELO DE LEITURA · FLOW</div><h3>O que o Flow precisa encontrar nesta tela</h3><p>Os dados estão no JSON; o módulo relaciona os IDs e apresenta cada funcionalidade.</p></div><div class="f-read-numbers"><span><b>${counts.jornadas}</b> ocorrências</span><span><b>${counts.relacoes}</b> relações</span><span><b>${counts.entradas}</b> entradas</span><span><b>${counts.componentes}</b> componentes</span></div></div><div class="f-read-actions">${focusButtons.map(([label,path])=>`<button data-field="${esc(JSON.stringify(path))}">${esc(label)}</button>`).join('')}</div></section><div class="f-screen-selection"><label>Tela analisada ${screensSelect(id)}</label><button class="f-btn" data-action="showJson">Ver tela completa</button><button class="f-btn" data-action="export">↓ Exportar JSON</button></div><div class="f-workspace-grid"><section class="f-panel"><div class="f-panel-head"><div><div class="f-eyebrow">01 / ÁRVORE</div><h3>Campos vistos pelo Flow</h3></div><span class="f-chip">Somente leitura</span></div><div class="f-search"><input id="fieldSearch" type="search" placeholder="Buscar campo ou caminho..." value="${esc(S.fieldQuery||'')}" aria-label="Buscar campos"><button title="Limpar pesquisa" data-action="clearFieldSearch">⊞</button></div><div class="f-tree-guide"><span style="color:#09a99a">●</span> Usado pelo motor &nbsp; <span style="color:#cdd9da">●</span> Não priorizado</div><div class="f-tree-scroll">${fieldTreeHtml(t)}</div><div class="f-tree-footer"><span class="mini">Selecione um campo para visualizar os detalhes.</span></div></section><section class="f-panel" id="detailPanel">${fieldDetails()}</section></div><footer class="f-note">Fonte de dados: <code>modulo.json</code>. O material da referência foi utilizado somente como padrão visual.</footer></div></div>`}
function findJourney(id){return jIndex().find(j=>j.id===id)||jIndex()[0]}
function journeyItems(j,sub){if(!j)return[];return [...j.subs.values()].filter(s=>!sub||sub===s.id).sort((a,b)=>a.order-b.order).flatMap(s=>s.items.sort((a,b)=>a.order-b.order).map(i=>({...i,sub:s.name}))) }
function journeysView(){const j=findJourney(S.journey);if(!j)return `<div class="empty">Nenhuma jornada classificada nos contratos.</div>`;S.journey=j.id;
 const options=[...j.subs.values()].sort((a,b)=>a.order-b.order);const items=journeyItems(j,S.subjourney).filter(x=>!S.query||nameOf(x.id).toLowerCase().includes(S.query.toLowerCase())||x.id.includes(S.query.toLowerCase()));
 const show=items.slice(0,S.showCount);return `<div class="toolbar"><label>Jornada <select id="journeySelect">${jIndex().map(x=>`<option value="${esc(x.id)}" ${x.id===j.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Subjornada <select id="subjourneySelect"><option value="">Todas</option>${options.map(x=>`<option value="${esc(x.id)}" ${x.id===S.subjourney?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Dispositivo <select id="deviceSelect"><option value="mobile" ${S.device==='mobile'?'selected':''}>Mobile</option><option value="desktop" ${S.device==='desktop'?'selected':''}>Desktop</option></select></label><label>Buscar <input id="journeySearch" value="${esc(S.query)}" placeholder="Nome ou ID"></label><button data-action="addToJourney">Adicionar tela à jornada</button><button data-action="newJourney">Nova jornada</button></div><p class="mini">${items.length} participações encontradas. A ordem é a declarada no JSON, não uma ligação de fluxo presumida.</p><div class="gallery">${show.map(({id,sub,order},i)=>`<article class="screen-card"><div class="screen-card-head"><span>${String(order).padStart(2,'0')} · ${esc(sub)}</span><button data-preview="${esc(id)}" class="text-button">Detalhes</button></div><div class="frame-mini ${S.device}"><iframe class="screen-iframe" sandbox="allow-scripts" data-screen="${esc(id)}" loading="lazy" title="Prévia ${esc(nameOf(id))}"></iframe><button class="cover-button" data-preview="${esc(id)}" title="Abrir prévia da tela"></button></div><div class="screen-card-foot"><strong>${esc(nameOf(id))}</strong><code>${esc(id)}</code></div></article>`).join('')}</div>${items.length>S.showCount?`<div class="load-more"><button data-action="moreScreens">Mostrar mais telas (${items.length-S.showCount})</button></div>`:''}`;
}
function getRels(id){return dt(tOf(id).navegacao?.relacoes).filter(r=>r&&typeof r==='object')}
function relTarget(r){const d=r.destino;return typeof d==='string'?d:d?.ref||d?.telaRef||''}
function relType(r){return r.destino?.tipo||r.destinoTipo||'não definido'}
function flowRelationSummary(id){const out=getRels(id),incoming=[];for(const sid of screenIDs())if(sid!==id)for(const r of getRels(sid))if(relTarget(r)===id)incoming.push({from:sid,r});return {out,incoming}}
function flowDetail(id){const data=flowRelationSummary(id),tab=S.flowDetailTab||'saidas';let content='';if(tab==='saida' || tab==='saidas'){content=`<div class="branch-options">${data.out.map((r,i)=>`<div class="branch-option"><div class="branch-node-kind">${i+1}</div><div style="min-width:0;flex:1"><strong>${esc(r.rotulo||r.opcao||r.id||'Relação')}</strong><p>${esc(r.descricao||r.tipo||'Conexão declarada')}</p><code>${esc(relType(r))} → ${esc(relTarget(r)||'sem destino')}</code>${r.condicaoRef?`<p style="color:#986d22">Condição: ${esc(r.condicaoRef)}</p>`:''}</div>${scr()[relTarget(r)]?`<button data-go="${esc(relTarget(r))}">Abrir destino</button>`:''}</div>`).join('')||'<div class="flow-empty">Não existem relações de saída declaradas para esta tela.</div>'}</div>`}
else if(tab==='entradas'){content=`<div class="branch-options">${data.incoming.map((x,i)=>`<div class="branch-option"><div class="branch-node-kind">↳</div><div style="min-width:0;flex:1"><strong>${esc(nameOf(x.from))}</strong><p>${esc(x.r.rotulo||x.r.tipo||'Relação de entrada')}</p><code>${esc(x.from)}</code></div><button data-go="${esc(x.from)}">Examinar</button></div>`).join('')||'<div class="flow-empty">Nenhuma entrada encontrada entre as telas do módulo.</div>'}</div>`}
else if(tab==='previa'){content=`<div class="flow-preview"><div class="preview-frame ${S.device}"><iframe class="screen-iframe" sandbox="allow-scripts" data-screen="${esc(id)}" title="Prévia da tela"></iframe></div></div>`}
else content=`<pre class="f-json">${esc(JSON.stringify(tOf(id),null,2))}</pre>`;
return `<section class="branch-card"><div class="branch-header"><div><strong>${esc(nameOf(id))}</strong><small style="display:block;margin-top:4px">${esc(id)}</small></div><button data-action="addRelation">＋ Conectar</button></div><div class="branch-tabs"><button class="${tab==='saidas'?'active':''}" data-flowtab="saidas">Saídas (${data.out.length})</button><button class="${tab==='entradas'?'active':''}" data-flowtab="entradas">Entradas (${data.incoming.length})</button><button class="${tab==='previa'?'active':''}" data-flowtab="previa">Prévia da tela</button><button class="${tab==='dados'?'active':''}" data-flowtab="dados">Contrato JSON</button></div><div class="branch-content">${content}</div></section>`}
function moveInFlow(id,dir){const j=jIndex().find(x=>x.id===S.journey);if(!j)return;const seq=[...new Set([...j.subs.values()].sort((a,b)=>a.order-b.order).filter(g=>!S.subjourney||g.id===S.subjourney).flatMap(g=>g.items.slice().sort((a,b)=>a.order-b.order)).map(x=>x.id))];const i=seq.indexOf(id),target=i+(dir==='up'?-1:1);if(i<0||target<0||target>=seq.length)return;const groupFor=k=>dt(tOf(k).classificacao?.jornadas).find(x=>x.jornada?.id===j.id)?.subjornada?.id;if(groupFor(seq[i])!==groupFor(seq[target])){alert('A movimentação entre subjornadas exige alterar a classificação da tela no contrato.');return}[seq[i],seq[target]]=[seq[target],seq[i]];seq.forEach((key,n)=>{for(const x of dt(tOf(key).classificacao?.jornadas))if(x.jornada?.id===j.id&&(!S.subjourney||x.subjornada?.id===S.subjourney))x.ordemTela=n+1});touch();renderPane()}
function forkCard(item){const id=item.id,r=getRels(id),uniqueTargets=new Set(r.map(relTarget).filter(Boolean)),context=item.p?.contexto||{},decisions=r.filter(x=>x.tipo==='decisao');if(!(context.branch&&uniqueTargets.size>1||decisions.length>1))return '';
const groups=new Map();for(const rel of r){const label=rel.rotulo||rel.opcao||nameOf(relTarget(rel))||'Destino';let group='Outros';if(/cadast|conta|registr/i.test(label+' '+relTarget(rel)))group='Cadastrar';else if(/senha|recuper|esqueceu/i.test(label+' '+relTarget(rel)))group='Esqueceu a senha';else if(/entrar|login|autentica|onboard|home|perfil/i.test(label+' '+relTarget(rel)))group='Entrar';if(!groups.has(group))groups.set(group,[]);groups.get(group).push(rel)}
const tabs=[...groups].filter(([,list])=>list.length);if(!tabs.length)return '';const activeTab=S.forkTabs?.[id]||tabs[0][0],selected=tabs.find(x=>x[0]===activeTab)||tabs[0];const title=id==='auth.sessao.entrar'?'Fluxo de login':context.branch||'Bifurcação';return `<section class="branch-card flow-fork-card"><div class="branch-header"><div class="fork-head"><span class="kind-badge state">BIFURCAÇÃO</span> <strong>${esc(title)}</strong></div><div class="flow-card-actions"><button data-flowmove="${esc(id)}:up">↑</button><button data-flowmove="${esc(id)}:down">↓</button><button data-selectscreen="${esc(id)}">Editar</button></div></div><div class="branch-tabs">${tabs.map(([label,list])=>`<button class="${label===selected[0]?'active':''}" data-forktab="${esc(id)}" data-tab="${esc(label)}">${esc(label)} <small>${list.length}</small></button>`).join('')}</div><div class="branch-content"><div class="fork-inner"><div class="f-eyebrow">DESTINOS DECLARADOS</div>${selected[1].slice(0,9).map((rel,i)=>`<div class="fork-link"><span>${i+1}</span><div><strong>${esc(rel.rotulo||rel.opcao||nameOf(relTarget(rel)))}</strong><code>${esc(relTarget(rel)||'sem destino')}</code></div>${scr()[relTarget(rel)]?`<button data-go="${esc(relTarget(rel))}">Visual</button>`:''}</div>`).join('')}</div></div></section>`}
function flowView(){const journeys=jIndex();if(!journeys.length)return '<div class="flow-empty">Ainda não foram declaradas jornadas neste módulo.</div>';const j=journeys.find(x=>x.id===S.journey)||journeys[0];S.journey=j.id;const groups=[...j.subs.values()].sort((a,b)=>a.order-b.order||a.name.localeCompare(b.name));let items=groups.filter(g=>!S.subjourney||S.subjourney===g.id).flatMap(g=>g.items.slice().sort((a,b)=>a.order-b.order).map(x=>({...x,sub:g.name,subId:g.id})));const q=(S.query||'').toLocaleLowerCase('pt-BR');if(q)items=items.filter(x=>(x.id+' '+nameOf(x.id)+' '+x.sub).toLocaleLowerCase('pt-BR').includes(q));const uniq=new Set();items=items.filter(x=>!uniq.has(x.id)&&uniq.add(x.id));const relCount=items.reduce((n,x)=>n+getRels(x.id).length,0);return `<div class="flow-theme"><div class="flow-canvas"><header class="flow-canvas-head"><div><div class="f-eyebrow">FLUXO PRINCIPAL</div><h2>Advogado Já · Fluxo completo V2</h2></div><p>Arraste uma tela ou uma bifurcação inteira. A posição visual representa a sequência do fluxo.</p></header><details class="flow-collapsible"><summary>Filtros de jornada e pesquisa <span>${esc(j.name)} · ${items.length} telas</span></summary><div class="flow-filterbar"><label>Jornada<select id="journeySelect">${journeys.map(x=>`<option value="${esc(x.id)}" ${x.id===j.id?'selected':''}>${esc(x.name)} (${[...x.subs.values()].reduce((n,g)=>n+g.items.length,0)})</option>`).join('')}</select></label><label>Subjornada<select id="subjourneySelect"><option value="">Todas as subjornadas</option>${groups.map(g=>`<option value="${esc(g.id)}" ${g.id===S.subjourney?'selected':''}>${esc(g.name)} (${g.items.length})</option>`).join('')}</select></label><label>Buscar tela<input id="flowSearch" value="${esc(S.query||'')}" placeholder="Nome ou ID…" type="search"></label><label>Prévia<select id="deviceSelect"><option value="mobile" ${S.device==='mobile'?'selected':''}>Mobile</option><option value="desktop" ${S.device==='desktop'?'selected':''}>Desktop</option></select></label><button data-action="clearFlowSearch">Limpar</button></div></details><div class="flow-sequence">${items.length?items.map((item,i)=>{const p=item.p||{},r=getRels(item.id),pending=p.contexto?.pendente===true,active=item.id===S.screen&&S.flowDetailOpen;const slug=item.id.split('.');return `<div class="flow-sequence-slot"><div class="flow-card ${active?'is-selected':''} ${pending?'pending':''}" draggable="true" data-flowdrag="${esc(item.id)}"><button type="button" class="drag-handle" title="Arrastar">⋮⋮</button><div class="flow-card-body" data-selectscreen="${esc(item.id)}" tabindex="0" role="button"><div class="flow-card-meta"><span class="kind-badge">TELA</span> <span>${esc(slug[0])} · ${esc(slug[1]||item.sub)}</span></div><strong>${esc(nameOf(item.id))}</strong><small>${esc(item.id)}</small></div><div class="flow-card-actions"><span class="flow-status">Fluxo: ${pending?'pendente':'declarado'}</span><button data-flowmove="${esc(item.id)}:up" aria-label="Mover para cima">↑</button><button data-flowmove="${esc(item.id)}:down" aria-label="Mover para baixo">↓</button><button data-preview="${esc(item.id)}">Visual</button><button data-action="removeJourney" data-origin="${esc(item.id)}" class="danger">Remover</button></div></div>${active?flowDetail(item.id):''}${forkCard(item)}</div>`}).join(''):'<div class="flow-empty">Nenhuma tela corresponde aos filtros desta jornada.</div>'}</div><div class="f-note">${items.length} telas · ${relCount} relações declaradas em <code>modulo.json</code>. A ordenação altera as participações da jornada, não os IDs.</div></div></div>`}
function countPersist(){let rows=[];for(const id of screenIDs())for(const r of dt(tOf(id).dados?.persistencia))rows.push({screen:id,rec:r});return rows}
function countOps(){let rows=[];for(const id of screenIDs())for(const r of dt(tOf(id).dados?.operacoes))rows.push({screen:id,rec:r});return rows}
function visualFields(){return screenIDs().flatMap(id=>dt(tOf(id).dados?.camposDeInterface).map(x=>({id,field:x}))) }
function bankView(){const bf=S.bankView||'campos';const fields=visualFields();let body='';
 if(bf==='campos')body=`<div class="toolbar"><label>Filtrar telas <input id="bankSearch" placeholder="ID, campo ou perfil" value="${esc(S.query)}"></label><span class="count">${fields.length} campos visuais documentados</span><button data-action="mapField">Vincular campo a entidade</button></div><div class="notice">Os campos abaixo foram identificados em formulários do Protótipo. Eles não equivalem automaticamente a colunas de banco.</div><div class="table-wrap"><table><thead><tr><th>Tela</th><th>Campo visual</th><th>Tipo</th><th>Obrigatório na UI</th><th>Persistência</th></tr></thead><tbody>${fields.filter(x=>!S.query||(`${x.id} ${x.field.elementoHTMLRef}`).toLowerCase().includes(S.query.toLowerCase())).slice(0,300).map(x=>`<tr><td><button class="cell-link" data-go="${esc(x.id)}">${esc(x.id)}</button></td><td>${esc(x.field.elementoHTMLRef)}</td><td>${esc(x.field.tipoVisual)}</td><td>${x.field.obrigatorioVisual?'Sim':'—'}</td><td><span class="status-pending">A mapear</span></td></tr>`).join('')}</tbody></table></div>`;
 else if(bf==='tabelas'){const rows=countPersist();body=`<div class="toolbar"><span>${rows.length} declarações explícitas de persistência</span><button data-action="mapField">+ Declarar mapeamento</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Tela</th><th>Entidade</th><th>Campo</th><th>Definição</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.screen)}</td><td>${esc(x.rec.entidadeRef||'não declarada')}</td><td>${esc(x.rec.campoRef||'não declarado')}</td><td><code>${esc(JSON.stringify(x.rec).slice(0,220))}</code></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><b>Nenhuma tabela homologada</b><p>A biblioteca não possui ainda mapeamentos persistentes. Identifique entidades, campos e operações por tela antes de desenhar um DER como fato.</p><button data-action="mapField">Declarar primeiro campo</button></div>`}`}
 else{const rows=countOps();body=`<div class="toolbar"><span>${rows.length} operações documentadas</span><button data-action="newOperation">+ Declarar operação</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Tela</th><th>Operação</th><th>Definição</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.screen)}</td><td>${esc(x.rec.id||'')}</td><td><code>${esc(JSON.stringify(x.rec).slice(0,220))}</code></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><b>Nenhuma operação declarada</b><p>Escolher leitura, gravação ou chamada de função exige uma decisão vinculada à tela. Nada será inferido pelo rótulo de botões.</p></div>`}`}
 return `<div class="subnav"><button data-nav="banco:campos" class="${bf==='campos'?'selected':''}">Campos por tela</button><button data-nav="banco:tabelas" class="${bf==='tabelas'?'selected':''}">Entidades / tabelas</button><button data-nav="banco:operacoes" class="${bf==='operacoes'?'selected':''}">Operações</button></div>${body}`}
function selectedScenario(){const all=S.bundle?.simulacoes?.cenarios||{};return all[S.scenario]||all[Object.keys(all)[0]]||{}}
function rotes(){return dt(S.bundle?.simulacoes?.jornadasSimuladas)}
function flattenRoteiro(list,choices=S.branchChoices){let out=[];for(const x of dt(list)){
 if(typeof x==='string')out.push({id:x});else if(x&&typeof x==='object'){
  if(x.screen)out.push({id:x.screen,fork:x.fork,question:x.question,choices:x.choices||[],effect:x.effect});
  if(!x.fork)out.push(...flattenRoteiro(x.steps,choices));
  else{const idx=choices[x.fork];if(Number.isInteger(idx)){const ch=x.choices?.[idx];if(ch)out.push(...flattenRoteiro(ch.steps,choices))}}
 }}return out}
function prototypeView(){const scenarios=S.bundle?.simulacoes?.cenarios||{},scenarioIds=Object.keys(scenarios),scripted=S.mode.startsWith('roteiro:');let r=rotes().find(x=>x.id===S.roteiro)||rotes()[0];if(r&&!S.roteiro)S.roteiro=r.id;
 let steps=scripted&&r?flattenRoteiro(r.steps):[];S.step=Math.max(0,Math.min(S.step,Math.max(steps.length-1,0)));
 if(scripted&&steps[S.step]?.id)S.screen=steps[S.step].id;
 else if(!S.screen)S.screen=selectedScenario().start||screenIDs()[0];
 const ss=selectedScenario();const active=scripted?steps[S.step]:null;
 const screen=S.screen;
 const links=getRels(screen).filter(x=>relType(x)==='tela' && scr()[relTarget(x)]);
 return `<div class="toolbar"><div class="segmented"><button data-nav="proto:livre" class="${!scripted?'selected':''}">Navegação livre</button><button data-nav="proto:roteiros" class="${scripted?'selected':''}">Apresentação de jornadas</button></div><label>Mock <select id="scenarioSelect">${scenarioIds.map(id=>`<option value="${esc(id)}" ${id===S.scenario?'selected':''}>${esc(scenarios[id].name||id)}</option>`).join('')}</select></label><label>Dispositivo <select id="deviceSelect"><option value="mobile" ${S.device==='mobile'?'selected':''}>Mobile</option><option value="desktop" ${S.device==='desktop'?'selected':''}>Desktop</option></select></label><button data-action="resetMock">Reiniciar sessão</button></div>${scripted?`<div class="toolbar"><label>Roteiro <select id="roteiroSelect">${rotes().map(x=>`<option value="${esc(x.id)}" ${x.id===S.roteiro?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><span class="count">Etapa ${S.step+1} de ${steps.length}</span><button data-action="prevStep" ${S.step<1?'disabled':''}>← Anterior</button><button data-action="nextStep" ${S.step>=steps.length-1?'disabled':''}>Próxima →</button></div>`:`<div class="toolbar"><label>Selecionar tela ${screensSelect(screen)}</label><span class="count">Ações simuladas: ${links.length}</span></div>`}<div class="split prototype-split"><div class="center-col"><div class="prototype-heading"><strong>${esc(nameOf(screen))}</strong><code>${esc(screen)}</code></div><div class="preview-frame prototype-frame ${S.device}"><iframe class="screen-iframe" sandbox="allow-scripts" data-screen="${esc(screen)}" data-interactive="1" title="Protótipo interativo"></iframe></div><div class="actions-bar"><button data-action="protoBack">← Voltar</button>${links.map(rel=>`<button data-go="${esc(relTarget(rel))}">${esc(rel.rotulo||rel.opcao||nameOf(relTarget(rel)))}</button>`).join('')||'<span class="muted">Sem saída declarada nesta tela</span>'}</div></div><div class="rightpanel"><h3>Contexto simulado</h3><p class="mini">${esc(ss.description||'Dados fictícios de apresentação, nunca produção.')}</p><div class="facts"><div><b>Cenário</b><span>${esc(ss.name||S.scenario||'—')}</span></div><div><b>Estado da OAB (mock)</b><span>${esc(ss.status||'—')}</span></div><div><b>Cadastro</b><span>${ss.registered?'Simulado: concluído':'Simulado: pendente'}</span></div><div><b>Escritório</b><span>${ss.office?'Simulado: vinculado':'Sem vínculo simulado'}</span></div></div>${active?.fork?`<div class="fork"><b>${esc(active.question||'Escolha uma alternativa')}</b>${dt(active.choices).map((c,i)=>`<button data-choice="${esc(active.fork)}:${i}" class="${S.branchChoices[active.fork]===i?'selected':''}">${esc(c.label||'Alternativa '+(i+1))}</button>`).join('')}</div>`:''}<h3>Dados do mock</h3><details><summary>Inspecionar amostra</summary><pre>${esc(JSON.stringify(ss.data||{},null,2))}</pre></details><p class="notice">Sem chamadas HTTP, pagamentos ou gravações reais. Interações não documentadas não geram destinos.</p></div></div>`;
}
function treeHtml(obj){const result=[];for(const [cid,c] of Object.entries(obj?.componentes||{})){
 const nodes=c?.estrutura?.html?.elementos||{},root=c?.estrutura?.html?.raizRef; if(!root||!nodes[root])continue;
 const children={};for(const [key,n] of Object.entries(nodes)){const par=n.paiRef||'';(children[par]||=([])).push([key,n]);}
 for(const arr of Object.values(children))arr.sort((a,b)=>(a[1].ordem||0)-(b[1].ordem||0));
 const seen=new Set();function rec(id,depth=0){if(depth>65||seen.has(id))return '';seen.add(id);const n=nodes[id];if(!n)return '';let tag=String(n.tag||'div').toLowerCase();if(!/^[a-z][a-z0-9-]*$/.test(tag)||['script','iframe','object','embed','link','meta','style'].includes(tag))tag='div';let attrs='';for(const [k,v] of Object.entries(n.atributos||{})){if(!/^[a-zA-Z_:][\w:.-]*$/.test(k)||/^on/i.test(k)||['srcdoc'].includes(k.toLowerCase()))continue;if(['href','src'].includes(k.toLowerCase())&&/^\s*(javascript|https?):/i.test(String(v)))continue;attrs+=` ${k}="${esc(v)}"`}
 let text=esc(n.texto||'');let content=(children[id]||[]).map(([ck])=>rec(ck,depth+1)).join('');if(['img','input','br','hr','source','area','wbr'].includes(tag))return `<${tag}${attrs}>`;return `<${tag}${attrs}>${text}${content}</${tag}>`}
 result.push(rec(root));
 }
 return result.join('')}
const memo=new Map();function frameDoc(id,interactive){let key=id+':'+Number(interactive);if(memo.has(key))return memo.get(key);const obj=scr()[id];if(!obj)return '<p>Tela inexistente</p>';
 let html=treeHtml(obj),parts=[];const t=obj.tela||{};for(const v of Object.values(t.estrutura?.css?.regras||{}))if(typeof v==='string')parts.push(v);
 for(const c of Object.values(obj.componentes||{}))for(let rule of Object.values(c.estrutura?.css?.regras||{}))if(typeof rule==='string')parts.push(rule.replace(/:host\b/g,'html'));
 const tokens=Object.entries(t.estrutura?.css?.tokens||{}).map(([k,v])=>`${k}:${v};`).join('');
 const addon=`<script>(function(){document.addEventListener('click',function(e){var el=e.target.closest('a,button,[data-action],[data-goto]');if(!el)return;var target=el.getAttribute('data-goto')||'';var action=el.getAttribute('data-action')||'';if(action.indexOf('navegar.')===0)target=action.slice(8);if(el.tagName==='A')e.preventDefault();if(${interactive?'true':'false'} && target){window.parent.postMessage({type:'aj.simulacao.navegar',id:target},'*')}else if(${interactive?'true':'false'} && action){window.parent.postMessage({type:'aj.simulacao.acao',action:action},'*')}});})();<\/script>`;
 const doc=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>:root{${tokens}}html,body{margin:0;min-height:100%;background:#fff}*{box-sizing:border-box}${parts.join('\n')}</style></head><body>${html||'<p style="padding:16px">Tela sem composição visual disponível.</p>'}${addon}</body></html>`;memo.set(key,doc);return doc}
function injectFrames(pane){for(const f of pane.querySelectorAll('iframe[data-screen]')){f.srcdoc=frameDoc(f.dataset.screen,f.dataset.interactive==='1')}}
function modal(title,body){S.modal=true;let elm=$('#dialogOverlay');if(!elm){elm=make('div','modal-cover');elm.id='dialogOverlay';document.body.appendChild(elm)}elm.innerHTML=`<div class="modal"><div class="modal-head"><b>${esc(title)}</b><button data-action="closeModal" aria-label="Fechar">×</button></div><div class="modal-body">${body}</div></div>`;elm.style.display='flex';injectFrames(elm)}
function closeModal(){const m=$('#dialogOverlay');if(m)m.style.display='none';S.modal=false}
function preview(id){if(!scr()[id])return;S.screen=id;modal(nameOf(id),`<div class="preview-modal"><div class="preview-frame ${S.device}"><iframe class="screen-iframe" sandbox="allow-scripts" data-screen="${esc(id)}" title="Tela selecionada"></iframe></div><div class="modal-meta"><code>${esc(id)}</code><h3>Classificação</h3><pre>${esc(JSON.stringify(tOf(id).classificacao||{},null,2))}</pre><h3>Relações</h3><pre>${esc(JSON.stringify(getRels(id),null,2))}</pre><button data-action="showJson">Ver JSON integral</button></div></div>`)}
function showJson(){const id=S.screen||screenIDs()[0];modal('Contrato JSON · '+id,`<div class="modal-actions"><button data-action="copyScreen">Copiar JSON</button><button data-action="exportScreen">Exportar somente esta tela</button></div><pre class="bigjson">${esc(JSON.stringify(scr()[id],null,2))}</pre>`)}
function download(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)+'\n'],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function touch(){S.changes++;$('#saveStatus')&&($('#saveStatus').textContent='Alterações não exportadas');memo.clear()}
function askRelation(){modal('Adicionar relação explícita',`<form id="relationForm" class="form"><label>ID da relação <input name="id" required placeholder="relacao.advogado.home.destino"></label><label>Origem ${screensSelect(S.screen,'relationOrigin')}</label><label>Destino ${screensSelect('','relationDest')}</label><label>Tipo <select name="tipo"><option value="continuar">continuar</option><option value="decisao">decisao</option><option value="voltar">voltar</option></select></label><label>Condição (ID, opcional) <input name="condicao" placeholder="condicaoRef (sem inventar expressão)"></label><label>Rótulo <input name="rotulo"></label><button type="submit">Confirmar ligação no JSON local</button></form>`)}
function relationSubmit(f){const id=f.querySelector('[name="id"]').value.trim(),origin=$('#relationOrigin').value,dest=$('#relationDest').value;if(!id||!origin||!dest){alert('Preencha ID, origem e destino.');return}for(const s of screenIDs())if(getRels(s).some(r=>r.id===id)){alert('ID de relação já existe.');return}const nav=tOf(origin).navegacao;nav.relacoes||=[];nav.relacoes.push({id,tipo:f.querySelector('[name="tipo"]').value,origem:{tipo:'tela',ref:origin},destino:{tipo:'tela',ref:dest},rotulo:f.querySelector('[name="rotulo"]').value||null,condicaoRef:f.querySelector('[name="condicao"]').value||null,situacao:'declarada_pelo_editor'});touch();closeModal();S.screen=origin;shell()}
function newJourney(){modal('Nova jornada',`<form class="form" id="journeyForm"><p class="mini">Identifique a jornada explicitamente. Não geramos IDs por dedução do nome.</p><label>ID da jornada <input name="id" required placeholder="ex.: cliente"></label><label>Nome da jornada <input name="name" required></label><label>ID da primeira subjornada <input name="subid" required placeholder="ex.: cadastro"></label><label>Nome da subjornada <input name="subname" required></label><label>Tela inicial ${screensSelect(S.screen,'journeyScreen')}</label><button type="submit">Criar participação</button></form>`)}
function journeySubmit(f){const id=f.querySelector('[name="id"]').value.trim(),name=f.querySelector('[name="name"]').value.trim(),subid=f.querySelector('[name="subid"]').value.trim(),subname=f.querySelector('[name="subname"]').value.trim(),screen=$('#journeyScreen').value;if(!id||!name||!subid||!subname||!screen)return;const joins=tOf(screen).classificacao.jornadas||=[];if(joins.some(x=>x.id==='part.'+id+'.'+screen)){alert('Participação já existe.');return}joins.push({id:'part.'+id+'.'+screen,jornada:{id,nome:name,ordem:jIndex().length+1},subjornada:{id:subid,nome:subname,ordem:1},ordemTela:1,ocorrenciaNo:null,condicaoRef:null});tOf(screen).classificacao.jornadas=joins;touch();closeModal();S.journey=id;setMode('journey:'+id)}
function addToJourney(){const j=findJourney(S.journey);if(!j)return;modal('Incluir tela na jornada',`<form class="form" id="addScreenForm"><label>Tela ${screensSelect(S.screen,'addScreenId')}</label><label>Subjornada <select id="addSub">${[...j.subs.values()].map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><label>ID da participação <input name="id" required placeholder="part.${esc(j.id)}.tela"></label><label>Ordem da tela <input name="order" type="number" min="1" value="1" required></label><button type="submit">Adicionar participação</button></form>`)}
function addScreenSubmit(f){const sid=$('#addScreenId').value,j=findJourney(S.journey),sub=j.subs.get($('#addSub').value),pid=f.querySelector('[name="id"]').value.trim(),ord=+f.querySelector('[name="order"]').value;if(!sid||!pid||!sub||!ord)return;const cls=tOf(sid).classificacao;cls.jornadas||=[];if(cls.jornadas.some(p=>p.id===pid)){alert('Participação já existe.');return}cls.jornadas.push({id:pid,jornada:{id:j.id,nome:j.name,ordem:j.order},subjornada:{id:sub.id,nome:sub.name,ordem:sub.order},ordemTela:ord,ocorrenciaNo:null,condicaoRef:null});touch();closeModal();shell()}
function mapField(){modal('Declarar campo persistente',`<form id="bankForm" class="form"><p class="mini">Este mapeamento é uma decisão explícita no contrato da tela. Não transforma automaticamente outros formulários em tabelas.</p><label>Tela ${screensSelect(S.screen,'bankScreen')}</label><label>ID da declaração <input name="id" required placeholder="map.auth.usuario.email"></label><label>ID da entidade <input name="entity" required placeholder="entidade.usuario"></label><label>ID do campo persistente <input name="field" required placeholder="campo.usuario.email"></label><label>Campo visual de origem (opcional) <input name="origin" placeholder="reg-email"></label><label>Tipo lógico <select name="type"><option>texto</option><option>numero</option><option>data</option><option>booleano</option><option>objeto</option></select></label><button type="submit">Registrar no JSON local</button></form>`)}
function bankSubmit(f){const vals=Object.fromEntries(new FormData(f));if(!vals.id||!vals.entity||!vals.field)return;const screen=$('#bankScreen').value;const dat=tOf(screen).dados;dat.persistencia||=[];if(dat.persistencia.some(x=>x.id===vals.id)){alert('ID já declarado nesta tela');return}dat.persistencia.push({id:vals.id,entidadeRef:vals.entity,campoRef:vals.field,elementoHTMLRef:vals.origin||null,tipoLogico:vals.type,situacao:'declaracao_pelo_editor'});touch();closeModal();setMode('banco:tabelas')}
function newOperation(){modal('Declarar operação de dados',`<form class="form" id="operationForm"><label>Tela ${screensSelect(S.screen,'operationScreen')}</label><label>ID único <input name="id" required placeholder="op.auth.cadastro.salvar"></label><label>Tipo <select name="type"><option value="leitura">Leitura</option><option value="gravacao">Gravação</option><option value="chamada_funcao">Chamada de função</option></select></label><label>Recurso de destino (referência explícita) <input name="resource" required placeholder="entidade.usuario ou funcao.usuario.criar"></label><button type="submit">Registrar operação</button></form>`)}
function operationSubmit(f){const v=Object.fromEntries(new FormData(f));if(!v.id||!v.resource)return;const dat=tOf($('#operationScreen').value).dados;dat.operacoes||=[];if(dat.operacoes.some(x=>x.id===v.id)){alert('ID duplicado');return}dat.operacoes.push({id:v.id,tipo:v.type,recursoRef:v.resource,situacao:'declaracao_pelo_editor'});touch();closeModal();setMode('banco:operacoes')}
function handleClick(e){const a=e.target.closest('[data-action],[data-nav],[data-preview],[data-go],[data-choice],[data-field],[data-selectscreen],[data-flowtab],[data-forktab],[data-flowmove]');if(!a)return;e.preventDefault();if(a.dataset.nav){setMode(a.dataset.nav);return}if(a.hasAttribute('data-field')){try{S.fieldPath=JSON.parse(a.dataset.field)}catch(_){};const panel=$('#detailPanel');if(panel)panel.innerHTML=fieldDetails();document.querySelectorAll('.f-tree-node>summary').forEach(e=>e.classList.toggle('selected',e===a));return}if(a.dataset.selectscreen){const id=a.dataset.selectscreen;S.screen=S.screen===id&&S.mode==='visualizacao'&&S.flowDetailOpen?null:id;S.flowDetailOpen=!!S.screen;S.flowDetailTab='saidas';renderPane();return}if(a.dataset.flowtab){S.flowDetailTab=a.dataset.flowtab;renderPane();return}if(a.dataset.forktab){S.forkTabs||=(Object.create(null));S.forkTabs[a.dataset.forktab]=a.dataset.tab;renderPane();return}if(a.dataset.flowmove){const [id,dir]=a.dataset.flowmove.split(':');moveInFlow(id,dir);return}if(a.dataset.preview){preview(a.dataset.preview);return}if(a.dataset.go){if(!scr()[a.dataset.go])return;S.history.push(S.screen);S.screen=a.dataset.go;if(MODULO==='FLUXO'&&S.mode==='visualizacao'&&!dt(tOf(S.screen).classificacao?.jornadas).some(p=>p.jornada?.id===S.journey)){S.journey=dt(tOf(S.screen).classificacao?.jornadas)[0]?.jornada?.id||S.journey;S.subjourney=null}if(MODULO==='JORNADAS')preview(S.screen);else {S.flowDetailOpen=true;S.flowDetailTab='saidas';renderPane()}return}if(a.dataset.choice){const [fork,raw]=a.dataset.choice.split(':');S.branchChoices[fork]=Number(raw);S.step++;shell();return}const act=a.dataset.action;if(!act)return;
 if(act==='saveField'){const el=$('#fieldEditor');if(!el)return;try{const value=JSON.parse(el.value);const p=S.fieldPath||[];if(!p.length)throw Error('Selecione uma propriedade');let target=tOf(S.screen);for(const k of p.slice(0,-1))target=target[k];target[p[p.length-1]]=value;memo.clear();touch();renderPane()}catch(ex){alert('Valor JSON inválido: '+ex.message)}return}
 if(act==='copyField'){const val=fieldValue(S.fieldPath);if(navigator.clipboard?.writeText)navigator.clipboard.writeText(JSON.stringify(val,null,2));else alert('Área de transferência indisponível neste navegador.');return}
 if(act==='removeJourney'){const id=a.dataset.origin,j=S.journey;if(!id||!j)return;if(!confirm('Remover a participação desta tela da jornada '+j+'? A tela continuará no catálogo.'))return;const part=dt(tOf(id).classificacao?.jornadas);tOf(id).classificacao.jornadas=part.filter(x=>x.jornada?.id!==j);touch();renderPane();return}
 if(act==='clearFieldSearch'){S.fieldQuery='';renderPane();return}
 if(act==='clearFlowSearch'){S.query='';S.subjourney=null;renderPane();return}
 if(act==='toggleSidebar'){$('#sidebar')?.classList.toggle('open');return}
 if(act==='import'){$('#fileLoader')?.click();return}
 if(act==='export'){download(S.bundle,'modulo_'+MODULO.toLowerCase()+'_atualizado.json');S.changes=0;$('#saveStatus')&&($('#saveStatus').textContent='Exportado nesta sessão');return}
 if(act==='closeModal'){closeModal();return}
 if(act==='showJson'){showJson();return}
 if(act==='copyScreen'){navigator.clipboard?.writeText(JSON.stringify(current(),null,2));return}
 if(act==='exportScreen'){download({[S.screen]:current()},S.screen+'.json');return}
 if(act==='addRelation'){if(a.dataset.origin)S.screen=a.dataset.origin;askRelation();return}
 if(act==='moreScreens'){S.showCount+=24;renderPane();return}
 if(act==='newJourney'){newJourney();return}
 if(act==='addToJourney'){addToJourney();return}
 if(act==='mapField'){mapField();return}
 if(act==='newOperation'){newOperation();return}
 if(act==='prevStep'){S.step=Math.max(0,S.step-1);shell();return}
 if(act==='nextStep'){S.step++;shell();return}
 if(act==='protoBack'){S.screen=S.history.pop()||S.screen;shell();return}
 if(act==='resetMock'){S.history=[];S.screen=selectedScenario().start||screenIDs()[0];S.step=0;S.branchChoices={};shell();return}
}
function handleChange(e){const id=e.target.id,v=e.target.value;
 if(id==='screenSelect'){S.screen=v;S.fieldPath=['navegacao'];renderPane()}else if(id==='flowSearch'){S.query=v;renderPane()}else if(id==='fieldSearch'){S.fieldQuery=v;renderPane()}else if(id==='journeySelect'){S.journey=v;S.subjourney=null;S.screen=null;renderPane()}else if(id==='subjourneySelect'){S.subjourney=v||null;renderPane()}else if(id==='deviceSelect'){S.device=v;renderPane()}else if(id==='scenarioSelect'){S.scenario=v;S.screen=selectedScenario().start||S.screen;S.history=[];renderPane()}else if(id==='roteiroSelect'){S.roteiro=v;setMode('roteiro:'+v)}else if(['fieldSearch','journeySearch','bankSearch'].includes(id)){S.query=v;renderPane()}else if(id==='fileLoader'){
 const file=e.target.files?.[0];if(!file)return;file.text().then(txt=>{try{const j=JSON.parse(txt);if(!j||!j.telas||!j.modulo)throw Error('Falta o objeto telas/modulo');if(j.modulo.toUpperCase()!==MODULO)throw Error('JSON de outro módulo: '+j.modulo);S.bundle=j;S.screen=j.telas['auth.inicializacao.splash']?'auth.inicializacao.splash':Object.keys(j.telas)[0];S.changes=0;memo.clear();shell()}catch(err){alert('Arquivo inválido: '+err.message)}});e.target.value='';}
}
function handleSubmit(e){if(!['relationForm','journeyForm','addScreenForm','bankForm','operationForm'].includes(e.target.id))return;e.preventDefault();({relationForm:relationSubmit,journeyForm:journeySubmit,addScreenForm:addScreenSubmit,bankForm:bankSubmit,operationForm:operationSubmit})[e.target.id](e.target)}
window.addEventListener('message',e=>{if(!S.bundle||MODULO!=='PROTOTIPO')return;const data=e.data;if(data?.type==='aj.simulacao.navegar'&&typeof data.id==='string'){const id=data.id;if(!scr()[id])return;const possible=getRels(S.screen).some(r=>relTarget(r)===id&&relType(r)==='tela');if(!possible){alert('Destino não documentado como relação da tela atual.');return}S.history.push(S.screen);S.screen=id;shell()}else if(data?.type==='aj.simulacao.acao'){const msg='Evento local documentado: '+data.action+' · Sem efeito externo.';$('#saveStatus')&&($('#saveStatus').textContent=msg.slice(0,70))}});
// API mínima para o index escolher telas sem reproduzir os motores dos módulos.
window.AJWorkspace={navigate(mode){if(!S.bundle)return false;setMode(mode);return true},getMode(){return S.mode}};
document.addEventListener('click',handleClick);document.addEventListener('change',handleChange);document.addEventListener('submit',handleSubmit);

document.addEventListener('keydown',e=>{const el=e.target.closest?.('[data-selectscreen]');if(el&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click()}});
document.addEventListener('dragstart',e=>{const c=e.target.closest?.('[data-flowdrag]');if(!c)return;S.dragId=c.dataset.flowdrag;if(e.dataTransfer)e.dataTransfer.setData('text/plain',S.dragId)});
document.addEventListener('dragover',e=>{const c=e.target.closest?.('[data-flowdrag]');if(c&&S.dragId&&S.dragId!==c.dataset.flowdrag){e.preventDefault();c.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const c=e.target.closest?.('[data-flowdrag]');if(c)c.classList.remove('drag-over')});
document.addEventListener('drop',e=>{const c=e.target.closest?.('[data-flowdrag]');if(!c||!S.dragId||S.dragId===c.dataset.flowdrag)return;e.preventDefault();const j=jIndex().find(x=>x.id===S.journey);if(!j)return;const sub=[...j.subs.values()].filter(x=>!S.subjourney||x.id===S.subjourney);const seq=sub.flatMap(x=>x.items).sort((a,b)=>a.order-b.order);const unique=[...new Set(seq.map(x=>x.id))];const from=unique.indexOf(S.dragId),to=unique.indexOf(c.dataset.flowdrag);if(from<0||to<0)return;const groupFor=k=>dt(tOf(k).classificacao?.jornadas).find(x=>x.jornada?.id===S.journey)?.subjornada?.id;if(groupFor(unique[from])!==groupFor(unique[to])){alert('Para mudar de subjornada, altere a classificação da tela no contrato.');return}unique.splice(to,0,unique.splice(from,1)[0]);unique.forEach((id,i)=>{for(const pt of dt(tOf(id).classificacao?.jornadas))if(pt.jornada?.id===S.journey&&(!S.subjourney||pt.subjornada?.id===S.subjourney))pt.ordemTela=i+1});S.dragId=null;touch();renderPane()});
document.addEventListener('dragend',()=>{S.dragId=null;document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))});

async function start(){try{const response=await fetch('./modulo.json',{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const j=await response.json();if(j.modulo?.toUpperCase()!==MODULO)throw Error('módulo incompatível');S.bundle=j;S.screen=j.telas['auth.inicializacao.splash']?'auth.inicializacao.splash':Object.keys(j.telas)[0];S.scenario=Object.keys(j.simulacoes?.cenarios||{})[0]||null;S.mode=location.hash==='#visual'?'visualizacao':'campos';if(MODULO==='BANCO')S.bankView='campos';shell()}catch(err){app.innerHTML=`<div class="loader-error"><div class="brand-mark">AJ</div><h1>Carregar módulo ${esc(moduleName())}</h1><p>Este módulo não busca dados fora de sua pasta. Para abrir o <code>index.html</code> diretamente como arquivo local, selecione seu próprio <code>modulo.json</code>. Em servidor estático local, a leitura é automática.</p><input id="fallbackFile" type="file" accept=".json,application/json"><p class="mini">Detalhe técnico: ${esc(err.message)}</p></div>`;$('#fallbackFile').onchange=async e=>{try{const j=JSON.parse(await e.target.files[0].text());if(j.modulo?.toUpperCase()!==MODULO||!j.telas)throw Error('JSON incorreto');S.bundle=j;S.screen=j.telas['auth.inicializacao.splash']?'auth.inicializacao.splash':Object.keys(j.telas)[0];S.scenario=Object.keys(j.simulacoes?.cenarios||{})[0]||null;S.mode=location.hash==='#visual'?'visualizacao':'campos';if(MODULO==='BANCO')S.bankView='campos';shell()}catch(ex){alert(ex.message)}};}}
start();
})();
